function guardarKit() {
  if (_kitComponentesActual.some(function(c){return componenteKitVigente(c).productoNoEncontrado;})){notify('Hay componentes que ya no se encuentran en Productos. Revisalos antes de guardar');return;}
  var nombre = document.getElementById('kit-nombre').value.trim();
  if (!nombre) { notify('Ingresá un nombre para el kit'); return; }
  if (!_kitComponentesActual.length) { notify('Agregá al menos un producto al kit'); return; }

  var costoTotal = costoKitVigente({componentes:_kitComponentesActual});
  var margenPct  = parseFloat(document.getElementById('kit-margen').value) || 0;
  var precioVenta = precioKitConMargen(costoTotal, margenPct);
  if (precioVenta === null) { notify('El margen debe ser desde 0 hasta menos de 100%'); return; }

  var kit = {
    nombre,
    descripcion:  document.getElementById('kit-descripcion').value.trim(),
    categoria:    document.getElementById('kit-categoria').value,
    componentes:  _kitComponentesActual.map(componenteKitVigente),
    costoTotal:   Math.round(costoTotal*100)/100,
    margenPct,
    precioVenta:  Math.round(precioVenta*100)/100,
    actualizadoPor: currentUser||'',
    ts: Date.now()
  };

  if (_kitEditandoFbKey) {
    kit.codigo = KITS_DATA[_kitEditandoFbKey].codigo;
    return window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/kits/'+_kitEditandoFbKey), kit)
      .then(function(){ notify('✓ Kit actualizado'); volverListaKits(); });
  } else {
    var maxNum = Object.values(KITS_DATA).reduce(function(max,k){
      var n = parseInt((k.codigo||'').replace('KIT-',''))||0;
      return n > max ? n : max;
    }, 0);
    kit.codigo = 'KIT-' + String(maxNum+1).padStart(3,'0');
    return window.fbPush(window.fbRef(window.fbDB, 'sisventas/kits'), kit)
      .then(function(){ notify('✓ Kit creado: ' + kit.codigo); volverListaKits(); });
  }
}

function spAgregarNota() {
  var inp=document.getElementById('sp-modal-nota'), reclamoKey=SP_MODAL_KEY;
  if(!inp||!reclamoKey)return;
  if(inp._svSupportNotePending)return inp._svSupportNotePending;
  var texto=inp.value.trim();if(!texto)return;
  var r=SP_DATA[reclamoKey];if(!r)return;
  var hist=r.historial?r.historial.slice():[];
  hist.push({texto:texto,autor:currentUser||'sistema',ts:Date.now()});
  var boton=inp.parentElement&&inp.parentElement.querySelector('button');
  var tarea=function(){return window.fbUpdate(window.fbRef(window.fbDB,'sisventas/reclamos/'+reclamoKey),{historial:hist}).then(function(){
    if(SP_MODAL_KEY===reclamoKey&&inp.value.trim()===texto)inp.value='';
    notify('✓ Nota agregada');
  }).catch(function(e){notify('Error: '+e.message);});};
  var carga=window.SisVentas&&window.SisVentas.carga;
  var pending=Promise.resolve().then(function(){return carga&&typeof carga.ejecutarAccion==='function'?carga.ejecutarAccion({tipo:'guardar',clave:'support-note:'+reclamoKey,boton:boton},tarea):tarea();});
  inp._svSupportNotePending=pending.finally(function(){if(inp._svSupportNotePending===result)delete inp._svSupportNotePending;});
  var result=inp._svSupportNotePending;return result;
}

function guardarMaxComisionPct() {
  var el = document.getElementById('cfg-max-comision-pct');
  var val = parseFloat(el ? el.value : 10) || 10;
  APROBACION_CONFIG.maxComisionPct = val;
  return window.fbSet(window.fbRef(window.fbDB, 'sisventas/config/maxComisionPct'), val)
    .then(function(){ notify('✓ Tope máximo de comisión guardado: ' + val + '%'); })
    .catch(function(e){ notify('Error: ' + e.message); });
}

function guardarAlicuotaIVA(inputId, clave) {
  if (!window.fbDB) { notify('Sin conexión'); return; }
  var valor = parseFloat((document.getElementById(inputId)||{}).value) || 0;
  return window.fbGet(window.fbRef(window.fbDB, 'sisventas/config/impuestos')).then(function(snap) {
    var actual = snap.val() || {};
    actual[clave] = valor;
    return window.fbSet(window.fbRef(window.fbDB, 'sisventas/config/impuestos'), actual)
      .then(function(){ notify('✓ Alícuota guardada: ' + valor + '%'); })
      .catch(function(e){ notify('Error: '+e.message); });
  });
}

function guardarImpuestosGenerales() {
  if (!window.fbDB) { notify('Sin conexión'); return; }
  var datos = {
    ingresosBrutos:      parseFloat((document.getElementById('imp-ingbrutos')||{}).value) || 0,
    percepcionIva:       parseFloat((document.getElementById('imp-percepcion')||{}).value) || 0,
    retencionGanancias:  parseFloat((document.getElementById('imp-retencion')||{}).value) || 0,
    condicionFiscal:     (document.getElementById('imp-condicion')||{}).value || 'Responsable inscripto'
  };
  return window.fbGet(window.fbRef(window.fbDB, 'sisventas/config/impuestos')).then(function(snap) {
    var actual = snap.val() || {};
    Object.assign(actual, datos);
    return window.fbSet(window.fbRef(window.fbDB, 'sisventas/config/impuestos'), actual)
      .then(function(){ notify('✓ Impuestos guardados'); })
      .catch(function(e){ notify('Error: '+e.message); });
  });
}

