function guardarPeriodoVac() {
  var fkey = window._modalVacEmpKey || (document.getElementById('vac-emp-sel')?document.getElementById('vac-emp-sel').value:'');
  var desde=document.getElementById('vac-desde').value, hasta=document.getElementById('vac-hasta').value;
  var dias=parseInt(document.getElementById('vac-dias').value)||0;
  if (!fkey||!desde||!hasta) { notify('Completá los datos'); return; }
  var emp=Object.values(empData||{}).find(function(e){return e.fbKey===fkey;});
  if (hasta<desde || dias<=0) { notify('Revisá las fechas y la cantidad de días'); return; }
  var payload={
    empleadoId:fkey, empleadoNombre:emp?emp.nombre:'', desde:desde, hasta:hasta, dias:dias,
    obs:document.getElementById('vac-obs').value, ts:Date.now()
  };
  var periodoKey=window._modalVacPeriodoKey;
  var operacion=periodoKey
    ? window.fbUpdate(window.fbRef(window.fbDB,'sisventas/vacaciones/'+periodoKey),payload)
    : window.fbPush(window.fbRef(window.fbDB,'sisventas/vacaciones'),payload);
  return operacion.then(function(){
    notify(periodoKey?'✓ Período actualizado':'✓ Período registrado');
    window._modalVacPeriodoKey=null;
    cerrarModalNuevoGenerico();
    renderModuloVacaciones();
  });
}

function credGuardar() {
  if (!_credClienteId || !window.fbDB) { notify('Sin conexión'); return; }
  var tipo  = document.getElementById('cred-tipo').value;
  var desc  = document.getElementById('cred-desc').value.trim();
  var user  = document.getElementById('cred-user').value.trim();
  var pass  = document.getElementById('cred-pass').value.trim();
  if (!user && !pass) { notify('Ingresá al menos usuario o contraseña'); return; }
  var datos = {
    tipo, desc: desc || CRED_TIPO_LABELS[tipo],
    user, pass,
    serie:   document.getElementById('cred-serie').value.trim(),
    ip:      document.getElementById('cred-ip').value.trim(),
    puerto:  document.getElementById('cred-puerto').value.trim(),
    notas:   document.getElementById('cred-notas').value.trim(),
    ts:      Date.now(),
    editadoPor: currentUser || ''
  };
  var domicilioEl = document.getElementById('cred-domicilio');
  var selectedOwnerId = _credEditKey ? _credEditOwnerId : String(domicilioEl && domicilioEl.value || _credClienteId || '');
  var selectedOwner = _credClientesGrupo.find(function(owner){ return owner.fbKey === selectedOwnerId; }) || { fbKey:selectedOwnerId, legacyId:selectedOwnerId };
  var path = credRutaNueva(_credEditKey || '', selectedOwner.fbKey);
  var op = _credEditKey
    ? window.fbUpdate(window.fbRef(window.fbDB, path), datos)
    : window.fbPush(window.fbRef(window.fbDB, credRutaNueva('', selectedOwner.fbKey)), datos);
  return op.then(function() {
    notify('✓ Credencial guardada');
    credCerrarEditor();
    credCargar();
  }).catch(function(e){ notify('Error: '+e.message); });
}
